return $input.all().map((item) => {
  const step = item.json;

  return {
    json: {
      ...step,
      step: Number(step.step),
      image: {
        ...(step.image || {}),
    reference_images: Array.isArray(step.image?.reference_images) ?step.image.reference_images : [],
    reference_usage:step.image?.reference_usage || "",
    reference_strength:step.image?.reference_strength || "subtle",
    seed: 12345,
    output_format: "png"
  },
  has_reference_images: Array.isArray(step.image?.reference_images) && step.image.reference_images.length > 0
    },
  };
});

const step = $json;
const body = $('Weebhook').first().json.body || {};

const allReferences = Array.isArray(body.reference_images)
  ? body.reference_images
  : [];

const selectedIds = Array.isArray(step.image?.reference_images)
  ? step.image.reference_images
  : [];

const maxReferencesPerScene = 4;

const selectedReferences = selectedIds
  .map((id) => allReferences.find((ref) => String(ref.id) === String(id)))
  .filter(Boolean)
  .slice(0, maxReferencesPerScene);

if (!selectedReferences.length) {
  return [{
    json: {
      step_data: step,
      reference_error: "No matching reference image details found"
    }
  }];
}

return selectedReferences.map((reference, index) => ({
  json: {
    step_data: step,
    reference,
    reference_index: index + 1,
    total_references: selectedReferences.length,
    reference_warning: selectedIds.length > maxReferencesPerScene
      ? `Only first ${maxReferencesPerScene} reference images were used for this scene`
      : ""
  }
}));

const step = $json.step_data || $json;
const body = $('Weebhook').first().json.body || {};
const explainerId = body.explainer_id;

const error = $json.reference_error || 'Reference preparation failed';

const image = {
  ...(step?.image || {}),
  kie_ai_status: 'failed',
  kie_ai_error: error,
  generation_model: 'gemini',
};

return [{
  json: {
    explainer_id: explainerId,
    step: step?.step || null,
    provider: 'gemini',
    status: 'failed',
    image_url: null,
    key: null,
    error,
    image,
    step_payload: step
      ? {
          ...step,
          image,
        }
      : null,
  },
}];

const source = $json.step_data
  ? $json
  : $('Prepare Reference Downloads').all()[$itemIndex]?.json;

const binary = $input.first().binary?.data;

if (!source?.step_data || !binary) {
  return [{
    json: {
      step_data: source?.step_data,
      reference_error: `Reference binary missing for ${source?.reference?.id || "unknown"}`
    }
  }];
}

const buffer = await this.helpers.getBinaryDataBuffer(0, "data");
const base64 = buffer.toString("base64");

return [{
  json: {
    step_data: source.step_data,
    reference: source.reference,
    reference_index: source.reference_index,
    total_references: source.total_references,
    reference_warning: source.reference_warning || "",
    part: {
      inlineData: {
        mimeType: source.reference?.mime || binary.mimeType || "image/png",
        data: base64
      }
    }
  }
}];

const references = $json.references || [];
const first = references[0];
const step = first?.step_data;

if (!step) {
  return [{
    json: {
      image: {
        kie_ai_status: "failed",
        kie_ai_error: "Step data missing while preparing Gemini payload"
      }
    }
  }];
}

const body = $('Weebhook').first().json.body || {};
const orientation = body.orientation || "horizontal";
const visualStyle = body.visual_style || "";
const aspectRatio = orientation === "vertical" ? "9:16" : "16:9";

const referenceSummary = references.map((item, index) => {
  const ref = item.reference || {};
  return [
    `Reference ${index + 1}:`,
    `ID: ${ref.id}`,
    `Type: ${ref.type || "other"}`,
    `Label: ${ref.label || ""}`,
    `Description: ${ref.description || ""}`,
    `Usage note: ${ref.usage_note || ""}`,
    `Sensitive note: ${ref.sensitive_note || ""}`
  ].join("\n");
}).join("\n\n");

const prompt = [
  "Create one image for an animated explainer scene.",
  "",
  `Visual style: ${visualStyle}`,
  `Scene prompt: ${step.image.prompt}`,
  `Reference usage instruction: ${step.image.reference_usage || ""}`,
  `Reference strength: ${step.image.reference_strength || "normal"}`,
  "",
  "Reference image metadata:",
  referenceSummary,
  "",
  "Use all attached reference images as visual guidance.",
  "Integrate only the elements requested in the reference usage instruction.",
  "Do not create a collage unless explicitly requested.",
  "Preserve important identity cues such as logo colors, mascot shape, face identity, product UI, and readable brand text as much as possible.",
  "If references conflict, prioritize the scene prompt and reference_usage instruction.",
  "Generate one clean final scene image only. No explanation."
].join("\n");

const parts = [
  { text: prompt },
  ...references
    .map((item) => item.part)
    .filter(Boolean)
];

return [{
  json: {
    ...step,
    gemini_payload: {
      contents: [
        { parts }
      ],
      generationConfig: {
        responseModalities: ["image"],
        imageConfig: {
          aspectRatio
        }
      }
    }
  }
}];

const step = $('Prepare Gemini Payload').all()[$itemIndex]?.json;
const response = $input.first().json;

const parts = response?.candidates?.[0]?.content?.parts || [];
const imagePart = parts.find((part) => part.inlineData?.data);

if (!step) {
  return [{
    json: {
      image: {
        kie_ai_status: "failed",
        kie_ai_error: `Step data not found for Gemini itemIndex ${$itemIndex}`
      }
    }
  }];
}

if (!imagePart) {
  return [{
    json: {
      ...step,
      image: {
        ...step.image,
        kie_ai_status: "failed",
        kie_ai_error: "Gemini did not return an image",
        gemini_response: response
      }
    }
  }];
}

return [{
  json: {
    ...step,
    generated_image: {
      mime: imagePart.inlineData.mimeType || "image/png",
      data: imagePart.inlineData.data
    }
  }
}];

const step = $('If Has Reference').all()[$itemIndex]?.json;
const response = $input.first().json;
const body = $('Weebhook').first().json.body || {};

const explainerId = body.explainer_id;

if (!step) {
  return [{
    json: {
      explainer_id: explainerId,
      step: null,
      provider: 'qwen',
      status: 'failed',
      task_id: null,
      error: `Step data not found for itemIndex ${$itemIndex}`,
      image: {
        kie_ai_status: 'failed',
        kie_ai_error: `Step data not found for itemIndex ${$itemIndex}`,
        generation_model: 'qwen',
      },
    },
  }];
}

const taskId = response?.data?.taskId;
const code = response?.code;
const msg = response?.msg || 'Unknown KieAI error';

if (code !== 200 || !taskId) {
  const error = `KieAI createTask failed: ${msg}`;

  return [{
    json: {
      explainer_id: explainerId,
      step: step.step,
      provider: 'qwen',
      status: 'failed',
      task_id: null,
      error,
      response,
      image: {
        ...step.image,
        kie_ai_status: 'failed',
        kie_ai_error: error,
        kie_ai_response: response,
        generation_model: 'qwen',
      },
      step_payload: {
        ...step,
        image: {
          ...step.image,
          kie_ai_status: 'failed',
          kie_ai_error: error,
          kie_ai_response: response,
          generation_model: 'qwen',
        },
      },
    },
  }];
}

const image = {
  ...step.image,
  kie_ai_task_id: taskId,
  kie_ai_status: 'pending',
  generation_model: 'qwen',
};

return [{
  json: {
    explainer_id: explainerId,
    step: step.step,
    provider: 'qwen',
    status: 'pending',
    task_id: taskId,
    image,
    step_payload: {
      ...step,
      image,
    },
  },
}];

const step = $('Extract Gemini Image').all()[$itemIndex]?.json;
const response = $input.first().json;
const body = $('Weebhook').first().json.body || {};

const explainerId = body.explainer_id;
const url = response?.url || response?.data?.url;
const key = response?.key || response?.data?.key;

if (!step || !url) {
  const error = !step
    ? `Step data not found for Gemini itemIndex ${$itemIndex}`
    : 'Generated image upload failed';

  return [{
    json: {
      explainer_id: explainerId,
      step: step?.step || null,
      provider: 'gemini',
      status: 'failed',
      image_url: null,
      key: key || null,
      error,
      response,
      image: {
        ...(step?.image || {}),
        kie_ai_status: 'failed',
        kie_ai_error: error,
        upload_response: response,
        generation_model: 'gemini',
      },
      step_payload: step
        ? {
            ...step,
            generated_image: undefined,
            gemini_payload: undefined,
            selected_references: undefined,
            image: {
              ...step.image,
              kie_ai_status: 'failed',
              kie_ai_error: error,
              upload_response: response,
              generation_model: 'gemini',
            },
          }
        : null,
    },
  }];
}

const image = {
  ...step.image,
  kie_ai_status: 'done',
  kie_ai_image_url: url,
  generation_model: 'gemini',
};

return [{
  json: {
    explainer_id: explainerId,
    step: step.step,
    provider: 'gemini',
    status: 'done',
    image_url: url,
    key: key || null,
    image,
    step_payload: {
      ...step,
      selected_references: undefined,
      generated_image: undefined,
      gemini_payload: undefined,
      image,
    },
  },
}];
